inputs = ['vf', 'ujawj', 'xfdha', 'yc', 'hzfb']
outputs = ['vuk', 'ujawj', 'xukdha', 'yc', 'hixukb']

print("Detailed analysis:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"{i}: '{inp}' -> '{out}'")
    if inp != out:
        # Find where they differ
        min_len = min(len(inp), len(out))
        diff_pos = None
        for j in range(min_len):
            if inp[j] != out[j]:
                diff_pos = j
                break
        if diff_pos is None:
            if len(inp) < len(out):
                diff_pos = len(inp)
            else:
                diff_pos = len(out)

        print(f"  First difference at position {diff_pos}")
        if len(inp) < len(out):
            print(f"  Insertion: added '{out[diff_pos:]}' at position {diff_pos}")
        elif len(inp) > len(out):
            print(f"  Deletion: removed '{inp[diff_pos]}' at position {diff_pos}")
        else:
            print(f"  Substitution: '{inp[diff_pos]}' -> '{out[diff_pos]}'")
    print()

